// План specs/clients-import.md 2.1 / 2.2 (#4030e4, реджект 1 + проверка 17.11 импорта пользователем). PROD, admin, компания «test», десктоп 1280, EN.
// @writes @data: импортирует 3 клиентов «QA-Import <метка> Alpha/Bravo/Charlie» (CSV собирается в тесте), затем повторно тот же файл; в finally клиенты удаляются
// (Actions → Delete Customer). Только компания «test» (не «Onsite Locksmith»). Реальных SMS/почты нет.
// 2.1 — импорт: «Import finished / 3 clients added.», клиенты видны в Clients, ZIP с ведущим 0 сохранён (02108), Tags и Workiz client ID — в Notes;
//       Total Clients вырос на 3 без перезагрузки (#ed0636).
// 2.2 — повторный импорт того же файла: «0 new clients will be added. 3 already on file will be skipped.», «Import 0 clients» неактивна (идемпотентность, AC3).
// Факты 17.11: повторный импорт 0 новых; Tags + Workiz ID в Notes; ZIP 02108/07302 с 0; Total 68→71.
// Не сверено с сайтом при записи: где на карточке клиента показаны Notes и ZIP (проверяем текст страницы CustomerDetail).
import { test, expect } from '../../fixtures';
import { ROLE, deleteImported, importDialog, openImportWithFile, prepare, stamp, workizCsv, workizRows } from './import-helpers';

test.describe('Import clients — result and re-import (#4030e4)', () => {
  test('QA-AUTO: import 3 Workiz clients (ZIP with leading 0, Tags + Workiz ID in notes), then re-import the same file adds 0 #4030e4 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(240_000);
    const page = await asUser(ROLE);
    await page.setViewportSize({ width: 1280, height: 800 });
    await prepare(page);
    const mark = stamp();
    const rows = workizRows(mark);
    const csv = workizCsv(rows);
    try {
      // 2.1 импорт
      const dialog = await openImportWithFile(page, `4030e4-${mark}.csv`, csv);
      await expect(dialog.getByText('3 new clients will be added.')).toBeVisible();
      await dialog.getByRole('button', { name: 'Import 3 clients' }).click();
      await expect(dialog.getByText('Import finished')).toBeVisible({ timeout: 60_000 });
      await expect(dialog.getByText('3 clients added.')).toBeVisible();
      await dialog.getByRole('button', { name: 'Close' }).click();

      await page.getByPlaceholder('Search clients...').fill(`QA-Import ${mark}`);
      for (const r of rows) {
        await expect(page.getByText(`${r.first} ${r.last}`, { exact: true }).first(), `клиент ${r.last} в списке`).toBeVisible({ timeout: 20_000 });
      }
      // Карточка Bravo: ZIP 02108 (ведущий 0), Tags и Workiz ID в заметках
      await page.getByText(`${rows[1].first} ${rows[1].last}`, { exact: true }).first().click();
      await page.waitForURL(/\/CustomerDetail/i, { timeout: 30_000 });
      const main = page.locator('main');
      await expect(main).toContainText('02108', { timeout: 20_000 });
      await expect(main).toContainText(rows[1].id);
      await expect(main).toContainText('Repeat');

      // 2.2 повторный импорт того же файла
      const again = await openImportWithFile(page, `4030e4-${mark}.csv`, csv);
      await expect(again.getByText(/0 new clients will be added\.\s*3 already on file will be skipped\./)).toBeVisible();
      await expect(again.getByRole('button', { name: 'Import 0 clients' })).toBeDisabled();
      await again.getByRole('button', { name: 'Cancel' }).click();
      await expect(importDialog(page)).toBeHidden();
    } finally {
      await deleteImported(page, mark);
    }
  });
});
